package vn.edu.hcmute.example3;
import java.security.SecureRandom; import java.time.*; import org.slf4j.*; import org.springframework.data.domain.PageRequest; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService {private static final Logger log=LoggerFactory.getLogger(AuthService.class); private final UserRepository users; private final OtpRepository otps; private final PasswordEncoder encoder; private final SecureRandom random=new SecureRandom(); AuthService(UserRepository u,OtpRepository o,PasswordEncoder e){users=u;otps=o;encoder=e;}
 @Transactional public void register(String username,String email,String fullName,String password){if(users.existsByUsernameOrEmail(username,email))throw new IllegalArgumentException("Tên tài khoản hoặc email đã được sử dụng."); users.save(new AppUser(username,email,encoder.encode(password),fullName,"USER",false)); issue(email,"ACTIVATE");}
 @Transactional public void issue(String email,String purpose){String code="%06d".formatted(random.nextInt(1_000_000)); otps.save(new OtpToken(email,encoder.encode(code),purpose,Instant.now().plus(Duration.ofMinutes(10)))); log.info("Mã xác nhận {} cho {}: {}",purpose,email,code);}
 @Transactional public boolean verify(String email,String purpose,String code){var list=otps.findActive(email,purpose,PageRequest.of(0,1)); if(list.isEmpty())return false; var otp=list.getFirst(); if(otp.getExpiresAt().isBefore(Instant.now())||!encoder.matches(code,otp.getCodeHash()))return false; otp.consume(); if("ACTIVATE".equals(purpose))users.findByEmail(email).orElseThrow().activate(); return true;}
 @Transactional public void reset(String email,String code,String password){if(!verify(email,"RESET",code))throw new IllegalArgumentException("Mã xác nhận không đúng hoặc đã hết hạn."); users.findByEmail(email).orElseThrow(()->new IllegalArgumentException("Không tìm thấy tài khoản.")).changePassword(encoder.encode(password));}
}
